/** First commercial-generation milestone. Not the P2 arbitrary-page editor. */
export const presentationLimits = { files: 5, fileBytes: 2_000_000, totalBytes: 10_000_000, envelopeBytes: 13_600_000, sourceCharacters: 40_000, slides: 25 } as const;
export type PresentationBrief = { goal: string; audience: string; scenario: 'business-report' | 'pitch-deck' | 'data-analysis'; theme: 'consulting' | 'corporate' | 'technology'; slideCount: number };
export type PresentationRequest = { schemaVersion: 1; brief: PresentationBrief; files: { name: string; base64: string }[] };
export type PresentationBlock = { id: string; sourceId: string; locator: string; text: string };
export type PresentationDataset = { id: string; sourceId: string; sheet: string; headers: string[]; rows: { row: number; values: string[] }[] };
export type PresentationSources = { inputHash: string; files: { id: string; name: string; sha256: string; bytes: number }[]; blocks: PresentationBlock[]; datasets: PresentationDataset[]; warnings: string[] };
export type PresentationCheckpoint = { kind: 'presentation'; schemaVersion: 1; inputHash: string; stage: 'planned'; spec: unknown; plannerModel?: string; usage?: unknown[] };

export function presentationQuality(spec: PresentationSpec, sources: PresentationSources, layout: ResolvedText[], render: { report?: Record<string, any>; error?: string }, pdf: { pageCount?: number; missingFonts?: string[]; error?: string }) {
  const issues = checkPresentationLayout(layout);
  const sourceNumbers = new Set((sources.blocks.map(b => b.text).join('\n').match(/[-+]?\d+(?:\.\d+)?(?:%|％)?/g) || []));
  for (const slide of spec.slides) {
    const { sources: _refs, speakerNotes: _notes, ...visible } = slide.content;
    const numbers = [...new Set(JSON.stringify(visible).match(/[-+]?\d+(?:\.\d+)?(?:%|％)?/g) || [])].filter(n => !sourceNumbers.has(n));
    if (numbers.length) issues.push({ severity: 'warning', code: 'UNMATCHED_NUMBER', slideId: slide.id, message: `材料中未按相同字面找到数字 ${numbers.slice(0, 12).join('、')}；可能是建议/编号/格式差异，必须逐项核对，不自动认定真实或伪造。` });
  }
  for (const box of layout) {
    if (box.color && ratio(box.color, box.fill || spec.theme.background) < (box.fontSize >= 18 ? 3 : 4.5)) issues.push({ severity: 'critical', code: 'LOW_TEXT_CONTRAST', slideId: box.slideId, elementId: box.elementId, message: '文字与已知背景的色彩对比度不足。' });
  }
  if (render.error || !render.report) issues.push({ severity: 'critical', code: 'RENDER_FAILED', message: render.error || '无逐页渲染证据。' });
  if (render.report && (render.report.pageCount !== spec.slides.length || render.report.missingFontCount)) issues.push({ severity: 'critical', code: 'RENDER_COUNT_OR_FONTS', message: '渲染页数不一致或存在缺失字体。' });
  if (pdf.error || pdf.pageCount !== spec.slides.length || pdf.missingFonts?.length) issues.push({ severity: 'critical', code: 'PDF_FAILED', message: pdf.error || 'PDF页数不一致或字体缺失。' });
  spec.missingInformation.forEach(message => issues.push({ severity: 'warning', code: 'MISSING_INFORMATION', message }));
  return {
    schemaVersion: 1, executionStatus: 'completed', releaseStatus: issues.some(i => i.severity === 'critical') ? 'blocked' : 'needs-human-review', commercialApproval: false,
    checks: { schema: 'passed', sourceReferences: 'all IDs resolved; semantic support NOT verified', chartAndTableData: 'deterministic verbatim cell bindings; no model-supplied values or implicit aggregation', nativeEditableObjects: 'compiler-authored text/shapes/charts/tables; no target-application editing certification', boundingBoxesAndTextMetrics: 'checked with bundled font; conservative heuristic, not Office text-overflow proof', textIntersections: 'checked; backgrounds and chart-internal labels excluded', raster: render.report ? 'all pages rendered by LibreOffice' : 'failed', pdf: pdf.error ? 'failed' : `${pdf.pageCount ?? 0} physical pages checked` },
    issues, sourceWarnings: sources.warnings, font: { ...presentationFont, bundledFontHashVerified: true, embeddedInPPTX: false },
    repair: { maxPlanningSchemaRetries: 1, automaticVisualRepair: false, factsDroppedToFit: false, fontShrinkingEnabled: false },
    notChecked: ['Independent semantic fact verification and contradiction resolution', 'Source rights, trademarks, confidential-data policy and provider retention', 'Office-native line breaking, native chart label collisions, aesthetic balance and all shape/shape occlusions', 'Editable reopening in Microsoft PowerPoint / Keynote / WPS and font substitution on recipient machines', 'Commercial approval by a named human reviewer'],
    nextAction: '对照 sources-and-notes.json、PDF及每页JPEG复核；blocked 时不得作为正式稿。没有critical也仍是待人工验收的草稿。',
  };
}

export async function createPresentation(input: SkillInput, event: (s: string) => void) {
  if (!input.owner || input.parameters?.externalConsent !== 'yes') throw Error('需要已认证的所有者和本次正文处理授权；未发送材料。');
  const request = parsePresentationRequest(input.bytes), hash = sha256(input.bytes);
  event('阶段 1/5：校验需求与所有材料；不截断、不执行公式或材料中的指令。');
  const sources = await readPresentationSources(request, hash);
  const fonts = presentationFonts();
  let proposal: unknown, model = '', planningCalls = 0;
  let usage: UsageRecord[] = [];
  if (input.resumePresentation) {
    const cp = validatePresentationCheckpoint(input.resumePresentation, hash);
    proposal = cp.spec; model = cp.plannerModel || 'checkpoint'; usage = (cp.usage || []).map(validatePresentationUsage);
    compilePresentationSpec(proposal, request.brief, sources);
    event('阶段 2/5：已校验并复用持久化规划检查点；不重复发送正文、不重复调用模型。');
  } else {
    if (!process.env.AI_API_KEY && !process.env.OPENAI_API_KEY) throw Error('服务端AI模型未配置；不会用模板冒充AI规划。');
    event('阶段 2/5：将已授权的需求、提取正文与数据位置发送给服务端模型，规划叙事、页型与讲稿。');
    const prompt = JSON.stringify({ brief: request.brief, files: sources.files, blocks: sources.blocks, datasets: sources.datasets.map(({ rows: _rows, ...d }) => d), warnings: sources.warnings });
    let validationError = '';
    for (let attempt = 0; attempt < 2; attempt++) {
      // The existing provider adapter owns credentials, deadlines and usage accounting. No uploaded endpoint/key/model is accepted.
      const response = await requestAI({ serverConfigurationOnly: true, onUsage: record => { usage.push(validatePresentationUsage(record)); input.onAIUsage?.(record); }, userId: input.owner, systemPrompt: presentationPlanningInstructions, prompt: prompt + (validationError ? `\nThe previous proposal failed deterministic validation: ${validationError}. Return a corrected COMPLETE JSON object; preserve the supported facts, do not invent substitutes.` : ''), options: { temperature: 0.2, maxTokens: 14000 } });
      planningCalls++; model = response.model.slice(0, 200);
      try { proposal = parseModelJSON(response.content); compilePresentationSpec(proposal, request.brief, sources); validationError = ''; break; }
      catch (error) { validationError = error instanceof Error ? error.message.slice(0, 400) : '规划格式不合法。'; if (attempt === 1) throw Error(`规划两次均未通过校验，未生成误导性文件：${validationError}`); event('模型规划未通过来源/数据/结构校验；仅进行一次受限的规划重试。'); }
    }
    const cp: PresentationCheckpoint = { kind: 'presentation', schemaVersion: 1, inputHash: hash, stage: 'planned', spec: proposal, plannerModel: model, usage };
    validatePresentationCheckpoint(cp, hash);
    if (input.onPresentationCheckpoint) await input.onPresentationCheckpoint(cp);
  }

import type { UsageRecord } from '../../api/model-registry';
import { object, safeText } from './sources';
/** Worker messages are attributed to the authenticated run owner, never an owner named by a model. */
export function validatePresentationUsage(value: unknown): UsageRecord {
  const u = object(value, ['model', 'provider', 'promptTokens', 'completionTokens', 'totalTokens', 'reported', 'latencyMs', 'status', 'error', 'createdAt'], '模型用量');
  safeText(u.model, 200, '模型标识'); safeText(u.provider, 50, '通道标识');
  for (const key of ['promptTokens', 'completionTokens', 'totalTokens']) if (u[key] !== null && (!Number.isSafeInteger(u[key]) || u[key] < 0 || u[key] > 1_000_000_000)) throw Error('模型用量未报告或格式不合法。');
  if (typeof u.reported !== 'boolean' || !['succeeded', 'failed'].includes(u.status) || typeof u.error !== 'string' || u.error.length > 1000 || !Number.isFinite(u.latencyMs) || u.latencyMs < 0 || u.latencyMs > 300000 || !Number.isSafeInteger(u.createdAt) || u.createdAt <= 0) throw Error('模型用量时间或状态不合法。');
  return u as UsageRecord;
}

